def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize distance matrix
    INF = float('inf')
    dist = [[INF] * n for _ in range(n)]

    # Set distance from s to itself as 0
    for i in range(n):
        dist[s][i] = INF
    dist[s][s] = 0

    # Relax edges up to n-1 times
    for _ in range(n-1):
        for u, v, w in edges:
            if dist[s][u] + w < dist[s][v]:
                dist[s][v] = dist[s][u] + w

    # Check if t is reachable
    if dist[s][t] == INF:
        return -1
    else:
        return dist[s][t]

