def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with Dijkstra's algorithm for shortest path
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    queue = deque()
    queue.append(s)

    while queue:
        u = queue.popleft()
        visited[u] = True

        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]:
                    queue.append(v)

    return dist[t] if dist[t] != float('inf') else -1

